const test=require('node:test'),assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path'); const engine=import('data:text/javascript;base64,'+Buffer.from(fs.readFileSync(path.join(__dirname,'../market-engine.js'),'utf8')).toString('base64'));
test('opening starts shopping and purchased goods finish at home',async()=>{const {simulateMarket}=await engine,r=simulateMarket();assert.equal(r.frames.find(f=>f.minute===540).people[1].state,'Shopping');assert.equal(r.summary.purchasesHome,6);assert.equal(r.frames.at(-1).stored,0);});
test('growth preserves booths and every destination has a walking route',async()=>{const {generateMarket,route}=await engine;for(const setting of ['mixed','indoor','outdoor'])for(let seed=1;seed<20;seed++){const a=generateMarket({seed,setting,bays:3}),b=generateMarket({seed,setting,bays:4});assert.deepEqual(b.stalls.slice(0,a.stalls.length),a.stalls);for(const n of b.nodes)assert(Number.isFinite(route(b,'home',n.id).distance));for(const s of b.stalls){assert.equal(s.corners.length,4);const entrance=b.nodes.find(n=>n.id===s.id);assert(Math.abs(entrance.x-(s.corners[0].x+s.corners[1].x)/2)<1e-8);assert(Math.abs(entrance.z-(s.corners[0].z+s.corners[1].z)/2)<1e-8);}assert(b.edges.length>b.nodes.length);assert.deepEqual(a,generateMarket({seed,setting,bays:3}));}});
test('weekly opening, staffing and role constraints are enforced',async()=>{const {simulateMarket}=await engine;assert.throws(()=>simulateMarket({people:1,purpose:'both'}),/two people/);for(let day=0;day<6;day++){const r=simulateMarket({day});assert.equal(r.summary.sold,0);assert.equal(r.summary.bought,0);assert(r.frames.every(f=>f.people.every(p=>p.state==='At home')));assert.equal(r.summary.stockHome,24);}for(const purpose of ['buy','sell']){const r=simulateMarket({people:1,purpose});assert.equal(r.summary.returned,1);assert.equal(r.summary.bought,purpose==='buy'?6:0);assert.equal(r.summary.sold,purpose==='buy'?0:24);}});
test('goods are conserved and sales only occur while staffed during opening hours',async()=>{const {simulateMarket}=await engine;for(const weather of ['clear','rain'])for(const distance of [200,3000])for(const departure of [6,12])for(const setting of ['indoor','outdoor']){const r=simulateMarket({weather,distance,departure,setting,bays:8});let prev=0;for(const f of r.frames){assert.equal(f.stockHome+f.reserve+f.boothStock+f.sold+f.people.reduce((s,p)=>s+p.carry,0),24);assert(f.boothStock>=0&&f.reserve>=0);assert.equal(f.purchasesHome+f.stored+f.people.reduce((s,p)=>s+p.bag,0),f.bought);if(f.sold>prev){assert(f.open);assert(r.transactions.some(t=>t.minute===f.minute&&t.staffed&&t.node===r.world.booth));}prev=f.sold;}assert.equal(r.summary.returned,2);assert(r.summary.bought<=6);assert.equal(r.summary.unsold+r.summary.sold,24);}});
test('longer paths delay arrival and rain changes outdoor demand',async()=>{const {simulateMarket}=await engine;const short=simulateMarket({distance:200}),long=simulateMarket({distance:3000});const unloaded=r=>r.events.find(e=>e.text.includes('finished at the drop-off')).minute;assert(unloaded(long)>unloaded(short));const clear=simulateMarket({setting:'outdoor'}),rain=simulateMarket({setting:'outdoor',weather:'rain'});assert(clear.summary.missed>rain.summary.missed);assert.deepEqual(short,simulateMarket({distance:200}));});




test('irregular mesh has convex shared quads and non-rectangular topology',async()=>{const {irregularGrid}=await engine;for(let seed=1;seed<=30;seed++){const g=irregularGrid(seed),valence=new Map();for(const e of g.edges){assert(e.faces.length===1||e.faces.length===2);valence.set(e.a,(valence.get(e.a)||0)+1);valence.set(e.b,(valence.get(e.b)||0)+1);}assert([...valence.values()].some(v=>v===3));assert([...valence.values()].some(v=>v>=5));for(const c of g.cells){const p=c.ids.map(i=>g.vertices[i]);for(let i=0;i<4;i++){const a=p[i],b=p[(i+1)%4],d=p[(i+2)%4];assert((b.x-a.x)*(d.z-b.z)-(b.z-a.z)*(d.x-b.x)>0,'folded quad');}const area=p.reduce((s,a,i)=>s+a.x*p[(i+1)%4].z-a.z*p[(i+1)%4].x,0)/2;assert(area>10);}}});

test('four styles grow deterministically with reachable stalls and a stable dry waterfront',async()=>{
 const {MARKET_STYLES,generateMarket,simulateMarket,route}=await engine;
 for(const style of Object.keys(MARKET_STYLES))for(const spacing of ['compact','comfortable','spacious'])for(let seed=1;seed<=12;seed++){
  const a=generateMarket({style,spacing,seed,bays:2}),b=generateMarket({style,spacing,seed,bays:8});
  assert.deepEqual(b.stalls.slice(0,8),a.stalls);assert.equal(b.stalls.length,32);
  for(const n of b.nodes)assert(Number.isFinite(route(b,'gate',n.id).distance));
  if(style==='canal'){assert.equal(a.waterfront.bankZ,b.waterfront.bankZ);assert(b.cells.every(c=>c.corners.every(p=>p.z<b.waterfront.bankZ)));}
 }
 for(const style of Object.keys(MARKET_STYLES)){const r=simulateMarket({style,bays:8,spacing:'spacious',distance:3000});assert.equal(r.summary.returned,2);assert.equal(r.summary.purchasesHome,6);assert.equal(r.summary.sold+r.summary.unsold,24);}
 const village=generateMarket({style:'village',bays:8}),arcade=generateMarket({style:'arcade',bays:8});
 const aspect=w=>(w.bounds.maxX-w.bounds.minX)/(w.bounds.maxZ-w.bounds.minZ);assert(aspect(arcade)>aspect(village)*1.5);
});
